    import re
    def parse_num(s):
        if not s: return None
        s = s.replace('\\text', '').replace('\\dfrac', '').replace('\\frac', '').replace('\\', '').replace('{', '').replace('}', '').replace(' ', '')
        if ',' in s:
            parts = s.split(',')
            if len(parts) > 1:
                try: return [float(p) for p in parts]
                except: return None
        try:
            return float(s)
        except:
            return None

    out = []
    for c, gt in zip(completions, answer):
        text = c[0]['content']
        pred_str = extract_solution(text)
        if is_correct(pred_str, gt):
            out.append(5.0)
            continue

        gt_val = parse_num(gt)
        pred_val = parse_num(pred_str)

        if gt_val is None or pred_val is None:
            out.append(-1.0)
            continue

        # Handle lists
        if isinstance(gt_val, list) or isinstance(pred_val, list):
            if isinstance(gt_val, list) and isinstance(pred_val, list):
                if len(gt_val) != len(pred_val):
                    out.append(-1.0)
                    continue
                total_dist = 0
                for g, p in zip(gt_val, pred_val):
                    denom = max(1.0, abs(g))
                    total_dist += abs(g - p) / denom
                avg_dist = total_dist / len(gt_val)
            else:
                out.append(-1.0)
                continue
        else:
            denom = max(1.0, abs(gt_val))
            avg_dist = abs(gt_val - pred_val) / denom

        # Reward: 5.0 at dist=0, 0.0 at dist=1.0, -1.0 at dist>=2.0
        if avg_dist < 1.0:
            score = 5.0 * (1.0 - avg_dist)
        else:
            score = -1.0 * min(1.0, (avg_dist - 1.0))
        out.append(score)
    return out

