def answer_format_convention(prompts, completions, answer, **kwargs):
    import re
    out = []
    for c, gt in zip(completions, answer):
        text = c[0]['content']
        pred_str = extract_solution(text)
        if not pred_str:
            out.append(-1.0)
            continue

        # Check for excessive whitespace
        if '  ' in pred_str or ' \n' in pred_str or '\n ' in pred_str:
            out.append(-0.5)
            continue

        # Check for redundant text like "Answer: " inside the solution tag
        if re.search(r'^(Answer|The answer|So the answer|Thus the answer)\s*[:=]', pred_str, re.IGNORECASE):
            out.append(-0.5)
            continue

        # Check for LaTeX commands that are not standard for simple numbers (e.g. \text for numbers)
        # If gt is a simple number, pred should ideally be a simple number or standard LaTeX
        if re.match(r'^\d+\.?\d*$', gt):
            if '\\text' in pred_str or '\\boxed' in pred_str:
                 out.append(-0.2) # Mild penalty for unnecessary formatting
            else:
                out.append(1.0)
        else:
            out.append(1.0)

        # If correct, boost the score
        if is_correct(pred_str, gt):
            out[-1] += 2.0

        return out

def concise_correctness_ratio(prompts, completions, answer, **kwargs):
    out = []
    for c, gt in zip(completions, answer):
        text = c[0]['content']
        pred_str = extract_solution(text)

        if is_correct(pred_str, gt):
            # Reward correctness, penalize length
            # Ideal length is ~500 chars, max ~2000
            length = len(text)
            if length < 500:
                score = 5.0
            elif length < 1000:
                score = 4.0
            elif length < 1500:
                score = 3.0
            elif length < 2000:
                score = 2.0
            else:
                score = 1.0
        else:
            # Incorrect: penalize length more heavily to discourage rambling on wrong answers
            length = len(text)
            if length < 500:
                score = -1.0
            elif length < 1000:
                score = -1.5
            elif length < 1500:
                score = -2.0
            else:
                score = -2.0
        out.append(score)
    return out

def group_relative_brevity(prompts, completions, answer, **kwargs):
    import math
    groups = {}
    for i, p in enumerate(prompts):
        groups.setdefault(str(p[-1]['content']), []).append(i)

    out = [0.0] * len(completions)

    for idx in groups.values():
        if len(idx) < 2:
            # Single sample, just use absolute length heuristic
            for i in idx:
                text = completions[i][0]['content']
                if is_correct(extract_solution(text), answer[i]):
                    out[i] = 2.0 if len(text) < 1000 else 1.0
                else:
                    out[i] = -1.0
            continue

        # Calculate lengths
        lengths = [len(completions[i][0]['content']) for i in idx]
        correct_flags = [is_correct(extract_solution(completions[i][0]['content']), answer[i]) for i in idx]

        # Only consider correct answers for brevity comparison
        correct_lens = [l for l, c in zip(lengths, correct_flags) if c]
        if not correct_lens:
            # All wrong, penalize all
            for i in idx:
                out[i] = -1.0
            continue

        avg_correct_len = sum(correct_lens) / len(correct_lens)

        for i, l, c in zip(idx, lengths, correct_flags):
            if c:
                # Score based on how much shorter than average correct length
                ratio = l / (avg_correct_len + 1e-6)
                if ratio < 0.8:
                    out[i] = 5.0
                elif ratio < 1.0:
                    out[i] = 4.0
                elif ratio < 1.2:
                    out[i] = 3.0
                elif ratio < 1.5:
                    out[i] = 2.0
                else:
                    out[i] = 1.0
            else:
                out[i] = -1.0
    return out

def thinking_to_solution_ratio(prompts, completions, answer, **kwargs):
    out = []
    for c, gt in zip(completions, answer):
        text = c[0]['content']
        thinking = extract_thinking(text)
        solution = extract_solution(text)

        if not thinking or not solution:
            out.append(-1.0)
            continue

        t_len = len(thinking)
        s_len = len(solution)

        # Ideal ratio is thinking > solution, but not excessively
        # If solution is very long, it might be rambling
        if s_len > 200:
            out.append(-1.0)
            continue

        ratio = t_len / (s_len + 1e-6)

        if is_correct(solution, gt):
            if 1.0 < ratio < 10.0:
                out.append(3.0)
            elif ratio <= 1.0:
                out.append(1.0) # Too little thinking
            else:
                out.append(2.0) # Too much thinking but still correct
        else:
            if ratio > 5.0:
                out.append(-2.0) # Rambling without success
            else:
                out.append(-1.0)
    return out

def majority_vote_agreement(prompts, completions, answer, **kwargs):
    groups = {}
    for i, p in enumerate(prompts):
        groups.setdefault(str(p[-1]['content']), []).append(i)

    out = [0.0] * len(completions)

    for idx in groups.values():
        if len(idx) < 2:
            for i in idx:
                if is_correct(extract_solution(completions[i][0]['content']), answer[i]):
                    out[i] = 1.0
                else:
                    out[i] = -1.0
            continue

        preds = [extract_solution(completions[i][0]['content']) for i in idx]

        # Cluster predictions
        clusters = []
        for i, p in enumerate(preds):
            if not p:
                continue
            found = False
            for cl in clusters:
                if is_correct(p, preds[cl[0]]):
                    cl.append(i)
                    found = True
                    break
            if not found:
                clusters.append([i])

        if not clusters:
            for i in idx:
                out[i] = -1.0
            continue

        top_cluster = max(clusters, key=len)

        for i in idx:
            if i in top_cluster:
                out[i] = 2.0
            else:
                out[i] = -1.0
    return out

def consensus_confidence(prompts, completions, answer, **kwargs):
    groups = {}
    for i, p in enumerate(prompts):
        groups.setdefault(str(p[-1]['content']), []).append(i)

    out = [0.0] * len(completions)

    for idx in groups.values():
        if len(idx) < 2:
            for i in idx:
                if is_correct(extract_solution(completions[i][0]['content']), answer[i]):
                    out[i] = 1.0
                else:
                    out[i] = -1.0
            continue

        preds = [extract_solution(completions[i][0]['content']) for i in idx]

        # Count unique answers
        unique_answers = {}
        for i, p in enumerate(preds):
            if not p:
                continue
            key = None
            for k in unique_answers:
                if is_correct(p, k):
                    key = k
                    break
            if key is None:
                unique_answers[p] = [i]
            else:
                unique_answers[key].append(i)

        if not unique_answers:
            for i in idx:
                out[i] = -1.0
            continue

        # Find the most common answer
        best_answer = max(unique_answers, key=lambda k: len(unique_answers[k]))
        best_count = len(unique_answers[best_answer])

        # Score based on agreement with the best answer and the strength of the consensus
        for i, p in enumerate(preds):
            if p and is_correct(p, best_answer):
                # Higher score if consensus is strong
                if best_count == len(idx):
                    out[i] = 3.0
                elif best_count > len(idx) / 2:
                    out[i] = 2.0
                else:
                    out[i] = 1.0
            else:
                out[i] = -1.0
    return out

def ngram_repetition_heavy(prompts, completions, answer, **kwargs):
    out = []
    for c in completions:
        text = c[0]['content']
        words = text.lower().split()
        if len(words) < 10:
            out.append(0.0)
            continue

        # 4-gram repetition
        grams = list(zip(words, words[1:], words[2:], words[3:]))
        if len(grams) == 0:
            out.append(0.0)
            continue

        unique_grams = len(set(grams))
        ratio = unique_grams / len(grams)

        # Penalty if ratio is low (high repetition)
        if ratio < 0.5:
            out.append(-2.0)
        elif ratio < 0.7:
            out.append(-1.0)
        elif ratio < 0.85:
            out.append(-0.5)
        else:
            out.append(0.5)
    return out

def rambling_sentence_penalty(prompts, completions, answer, **kwargs):
    import re
    out = []
    for c, gt in zip(completions, answer):
        text = c[0]['content']
        thinking = extract_thinking(text) or ''

        # Split into sentences
        sentences = re.split(r'[.!?]+', thinking)
        sentences = [s.strip() for s in sentences if s.strip()]

        long_sentences = sum(1 for s in sentences if len(s.split()) > 40)
        total_sentences = len(sentences)

        if total_sentences == 0:
            out.append(0.0)
            continue

        ratio = long_sentences / total_sentences

        if is_correct(extract_solution(text), gt):
            if ratio > 0.5:
                out.append(1.0) # Slight penalty for rambling even if correct
            else:
                out.append(3.0)
        else:
            if ratio > 0.5:
                out.append(-2.0) # Heavy penalty for rambling and incorrect
            else:
                out.append(-1.0)
    return out

def step_marker_density(prompts, completions, answer, **kwargs):
    import re
    pattern = re.compile(r"(Step \d+:|^\d+\.|\n-|\n\*|First,|Second,|Next,|Finally,)", re.MULTILINE)
    out = []
    for c, gt in zip(completions, answer):
        text = c[0]['content']
        thinking = extract_thinking(text) or ''

        markers = pattern.findall(thinking)
        count = len(markers)

        # Ideal is 3-10 steps
        if count < 3:
            score = 0.0
        elif count <= 10:
            score = 2.0
        elif count <= 15:
            score = 1.0
        else:
            score = -1.0 # Too many steps, likely overthinking

        if is_correct(extract_solution(text), gt):
            score += 1.0
        else:
            score -= 1.0

        out.append(score)
    return out

def verification_mention(prompts, completions, answer, **kwargs):
    import re
    out = []
    for c, gt in zip(completions, answer):
        text = c[0]['content']
        thinking = extract_thinking(text) or ''

        # Look for verification keywords
        verify_patterns = ['check', 'verify', 'verify that', 'checking', 'verification', 'plug in', 'substitute back', 'test the answer']
        found = any(p in thinking.lower() for p in verify_patterns)

        if found:
            score = 1.0
        else:
            score = -0.5

        if is_correct(extract_solution(text), gt):
            score += 2.0
        else:
            score -= 1.0

        out.append(score)
    return out

def correction_detection(prompts, completions, answer, **kwargs):
    import re
    out = []
    for c, gt in zip(completions, answer):
        text = c[0]['content']
        thinking = extract_thinking(text) or ''

        # Look for correction patterns
        correction_patterns = ['wait', 'actually', 'correction', 'oops', 'mistake', 'error', 'let me recalculate', 'i made a mistake', 'reconsider']
        found = any(p in thinking.lower() for p in correction_patterns)

        if found:
            # Corrections are good if they lead to the right answer
            if is_correct(extract_solution(text), gt):
                score = 2.0 # Successfully corrected
            else:
                score = -1.0 # Corrected but still wrong
        else:
            if is_correct(extract_solution(text), gt):
                score = 1.0 # Correct without needing correction
            else:
                score = -1.0

        out.append(score)
    return out

def simplified_answer_check(prompts, completions, answer, **kwargs):
    import re
    out = []
    for c, gt in zip(completions, answer):
        text = c[0]['content']
        pred_str = extract_solution(text)

        if not pred_str:
            out.append(-1.0)
            continue

        # Check for unsimplified fractions
        if '\\frac' in pred_str or '\\dfrac' in pred_str:
            # Try to parse and check if it simplifies
            # Simple check: if numerator and denominator are both even
            m = re.search(r'\\(?:d?frac)\{(\d+)\}\{(\d+)\}', pred_str)
            if m:
                num = int(m.group(1))
                den = int(m.group(2))
                if num % 2 == 0 and den % 2 == 0:
                    out.append(-1.0) # Unsimplified fraction
                    continue

        # Check for redundant 1.000000
        if re.search(r'\d+\.0+$', pred_str):
            out.append(-0.5)
            continue

        if is_correct(pred_str, gt):
            out.append(2.0)
        else:
            out.append(0.0)
    return out

